class Solution:
    MOD = 10**9 + 7
    def countNumbersWithNonDecreasingDigits(self, l: str, r: str, b: int) -> int:
        return (self.f(r, b) - self.f(self.dec(l), b)) % self.MOD
    def dec(self, s):
        a = list(s)
        i = len(a) - 1
        while i >= 0:
            if a[i] != '0':
                a[i] = chr(ord(a[i]) - 1)
                return ''.join(a)
            a[i] = '9'
            i -= 1
        return '0'
    def toBase(self, s, b):
        ds = [int(c) for c in s]
        out = []
        while ds:
            rem = 0
            nd = []
            for d in ds:
                cur = rem * 10 + d
                if nd or cur >= b:
                    nd.append(cur // b)
                rem = cur % b
            out.append(rem)
            ds = nd
        return out
    def f(self, s, b):
        import functools
        ds = self.toBase(s, b)
        n = len(ds)
        @functools.cache
        def go(i, p, tight):
            if i == n:
                return 1
            hi = ds[i] if tight else b - 1
            t = 0
            for v in range(p, hi + 1):
                t += go(i + 1, v, tight and v == ds[i])
            return t % self.MOD
        return go(0, 0, True) % self.MOD

