public:
    static const long long MOD = 1000000007LL;
    int b_; vector<int> ds_; vector<vector<long long>> memo_;
    long long go(int i, int p, bool tight) {
        if (i == (int)ds_.size()) return 1;
        if (!tight && memo_[i][p] >= 0) return memo_[i][p];
        int hi = tight ? ds_[i] : b_ - 1;
        long long t = 0;
        for (int v = p; v <= hi; ++v)
            t = (t + go(i + 1, v, tight && v == ds_[i])) % MOD;
        if (!tight) memo_[i][p] = t;
        return t;
    }
    long long f(const string& s) {
        ds_ = toBase(s);
        memo_.assign(ds_.size() + 1, vector<long long>(b_, -1));
        return go(0, 0, true);
    }
    vector<int> toBase(const string& s) {
        vector<int> ds;
        for (char c : s) ds.push_back(c - '0');
