            int rem = 0; vector<int> nd;
            for (int d : ds) {
                int cur = rem * 10 + d;
                if (!nd.empty() || cur >= b_) nd.push_back(cur / b_);
                rem = cur % b_;
            }
            out.push_back(rem);
            ds = nd;
        }
        return out;
    }
    string dec(string s) {
        int i = s.size() - 1;
        while (i >= 0) {
            if (s[i] != '0') { s[i]--; return s; }
            s[i--] = '9';
        }
        return "0";
    }
    int countNumbersWithNonDecreasingDigits(string l, string r, int b) {
        b_ = b;
        return ((f(r) - f(dec(l))) % MOD + MOD) % MOD;
    }
};

